fn ping() -> Int uses net or fail {
    return try fetch_status("https://api.example.com/ping")
}

fn main() uses io, net {
    for i in 0 to 3 {
        check ping() {
            ok code {
                print(to_text(code))
            }
            fail why {
                print(why)
            }
        }
    }
}

